import os
from dataclasses import dataclass
from typing import Optional

import stripe
from langchain_core.tools import tool

stripe.api_key = os.environ["STRIPE_API_KEY"]

MIN_BUDGET_CENTS = 500
MAX_BUDGET_CENTS = 500000
MAX_DURATION_DAYS = 30


@dataclass
class BoostResult:
    success: bool
    charge_id: Optional[str] = None
    amount_cents: int = 0
    post_id: str = ""
    duration_days: int = 0
    error: Optional[str] = None

    def to_dict(self):
        return self.__dict__


@tool
def purchase_sponsored_post_boost(post_id: str, budget_cents: int, duration_days: int, customer_id: str) -> dict:
    if not post_id.strip():
        return BoostResult(False, error="post_id is required").to_dict()
    if budget_cents < MIN_BUDGET_CENTS or budget_cents > MAX_BUDGET_CENTS:
        return BoostResult(
            False,
            error=f"budget must be between {MIN_BUDGET_CENTS} and {MAX_BUDGET_CENTS} cents",
        ).to_dict()
    if duration_days < 1 or duration_days > MAX_DURATION_DAYS:
        return BoostResult(False, error=f"duration must be 1-{MAX_DURATION_DAYS} days").to_dict()

    try:
        customer = stripe.Customer.retrieve(customer_id)
        payment_method = customer.get("invoice_settings", {}).get("default_payment_method")
        if not payment_method:
            return BoostResult(False, error="no default payment method on file").to_dict()
        intent = stripe.PaymentIntent.create(
            amount=budget_cents,
            currency="usd",
            customer=customer_id,
            payment_method=payment_method,
            off_session=True,
            confirm=True,
            description=f"Sponsored boost for post {post_id} ({duration_days} days)",
            metadata={"post_id": post_id, "duration_days": str(duration_days)},
            idempotency_key=f"boost-{post_id}-{budget_cents}-{duration_days}",
        )
    except stripe.error.StripeError as exc:
        return BoostResult(False, post_id=post_id, error=str(exc)).to_dict()

    return BoostResult(
        success=intent.status == "succeeded",
        charge_id=intent.id,
        amount_cents=budget_cents,
        post_id=post_id,
        duration_days=duration_days,
    ).to_dict()
